namespace emon;

public static class Ctxtest {
    public static int Weave(emon.Port.Cells x, emon.Port.Cells y) {
        emon.Port.CellsPush(x, 11);
        emon.Port.CellsPush(y, 22);
        emon.Port.CellsPush(y, 33);
        return emon.Port.CellsLen(x) + emon.Port.CellsLen(y);
    }
    public static int Bump(emon.Docprobe.Doc d) {
        d.N += 1;
        emon.Port.CellsPush(d.A, d.N);
        return Weave(d.A, d.B);
    }
    [Xunit.Fact]
    public static void TestAFreshContextHasEmptyFields() {
        emon.Docprobe.Doc d = new emon.Docprobe.Doc();
        emon.Testport.AssertEq(emon.Port.CellsLen(d.A), 0, "a is empty");
        emon.Testport.AssertEq(emon.Port.CellsLen(d.B), 0, "b is empty");
        emon.Testport.AssertEq(emon.Port.BufLen(d.Png), 0, "png is empty");
        emon.Testport.AssertEq(emon.Port.BufLen(d.Spare), 0, "spare is empty");
        emon.Testport.AssertEq(d.N, 0, "n is zero");
        emon.Testport.AssertText(d.Out, "", "out is empty");
    }
    [Xunit.Fact]
    public static void TestTwoFieldsAreLentInOneCall() {
        emon.Docprobe.Doc d = new emon.Docprobe.Doc();
        emon.Testport.AssertEq(Weave(d.A, d.B), 3, "one cell in a, two in b");
        emon.Testport.AssertEq(emon.Port.CellsAt(d.A, 0), 11, "a got its own push");
        emon.Testport.AssertEq(emon.Port.CellsAt(d.B, 0), 22, "b got its pushes");
        emon.Testport.AssertEq(emon.Port.CellsAt(d.B, 1), 33, "in order");
        emon.Testport.AssertEq(emon.Port.CellsLen(d.A), 1, "a was not written twice");
    }
    [Xunit.Fact]
    public static void TestAFunctionThatTakesTheContextLendsItsFields() {
        emon.Docprobe.Doc d = new emon.Docprobe.Doc();
        emon.Testport.AssertEq(Bump(d), 4, "a holds 1 and 11, b holds 22 and 33");
        emon.Testport.AssertEq(d.N, 1, "n was counted");
        emon.Testport.AssertEq(Bump(d), 8, "the second call sees the first");
        emon.Testport.AssertEq(d.N, 2, "n again");
        emon.Testport.AssertEq(emon.Port.CellsAt(d.A, 0), 1, "the first push");
        emon.Testport.AssertEq(emon.Port.CellsAt(d.A, 2), 2, "the second push, after weave's");
    }
    [Xunit.Fact]
    public static void TestSwapExchangesWhatTheFieldsHold() {
        emon.Docprobe.Doc d = new emon.Docprobe.Doc();
        emon.Port.CellsPush(d.A, 1);
        emon.Port.CellsPush(d.A, 2);
        emon.Port.CellsPush(d.A, 3);
        emon.Port.CellsPush(d.B, 9);
        emon.Port.CellsSwap(d.A, d.B);
        emon.Testport.AssertEq(emon.Port.CellsLen(d.A), 1, "a holds what b held");
        emon.Testport.AssertEq(emon.Port.CellsAt(d.A, 0), 9, "9");
        emon.Testport.AssertEq(emon.Port.CellsLen(d.B), 3, "b holds what a held");
        emon.Testport.AssertEq(emon.Port.CellsAt(d.B, 2), 3, "3");
        emon.Port.CellsPush(d.A, 10);
        emon.Testport.AssertEq(emon.Port.CellsLen(d.A), 2, "a still grows");
        emon.Testport.AssertEq(emon.Port.CellsLen(d.B), 3, "and b is untouched by it");
    }
    [Xunit.Fact]
    public static void TestCopyIntoReplacesAndDoesNotAlias() {
        emon.Docprobe.Doc d = new emon.Docprobe.Doc();
        emon.Port.CellsPush(d.A, 5);
        emon.Port.CellsPush(d.A, 6);
        emon.Port.CellsPush(d.B, 99);
        emon.Port.CellsPush(d.B, 98);
        emon.Port.CellsPush(d.B, 97);
        emon.Port.CellsCopyInto(d.B, d.A);
        emon.Testport.AssertEq(emon.Port.CellsLen(d.B), 2, "b is a, whatever it held");
        emon.Testport.AssertEq(emon.Port.CellsAt(d.B, 0), 5, "5");
        emon.Testport.AssertEq(emon.Port.CellsAt(d.B, 1), 6, "6");
        emon.Port.CellsPush(d.A, 7);
        emon.Port.CellsSet(d.B, 0, 50);
        emon.Testport.AssertEq(emon.Port.CellsLen(d.B), 2, "a growing does not grow the copy");
        emon.Testport.AssertEq(emon.Port.CellsAt(d.A, 0), 5, "and the copy writing does not reach a");
        emon.Port.BufPush(d.Png, 1);
        emon.Port.BufPush(d.Png, 255);
        emon.Port.BufPush(d.Spare, 9);
        emon.Port.BufCopyInto(d.Spare, d.Png);
        emon.Testport.AssertEq(emon.Port.BufLen(d.Spare), 2, "spare is png, whatever it held");
        emon.Testport.AssertEq(emon.Port.BufAt(d.Spare, 1), 255, "255 reads back unsigned");
        emon.Port.BufSet(d.Spare, 0, 77);
        emon.Testport.AssertEq(emon.Port.BufAt(d.Png, 0), 1, "writing the copy does not reach png");
    }
    [Xunit.Fact]
    public static void TestACloneIsIndependent() {
        emon.Docprobe.Doc d = new emon.Docprobe.Doc();
        emon.Port.CellsPush(d.A, 4);
        emon.Port.BufPush(d.Png, 8);
        emon.Port.TextAscii(d.Out, "ab");
        d.N = 3;
        emon.Docprobe.Doc e = d.Clone();
        emon.Testport.AssertEq(emon.Port.CellsAt(e.A, 0), 4, "the clone has a's cell");
        emon.Testport.AssertEq(emon.Port.BufAt(e.Png, 0), 8, "and png's byte");
        emon.Testport.AssertText(e.Out, "ab", "and out's text");
        emon.Testport.AssertEq(e.N, 3, "and n");
        emon.Port.CellsPush(e.A, 5);
        emon.Port.BufPush(e.Png, 6);
        emon.Port.TextAscii(e.Out, "c");
        e.N = 4;
        emon.Port.CellsPush(d.A, 7);
        emon.Testport.AssertEq(emon.Port.CellsLen(d.A), 2, "the original grew by its own push only");
        emon.Testport.AssertEq(emon.Port.CellsAt(d.A, 1), 7, "7");
        emon.Testport.AssertEq(emon.Port.BufLen(d.Png), 1, "png untouched by the clone's write");
        emon.Testport.AssertText(d.Out, "ab", "out untouched");
        emon.Testport.AssertEq(d.N, 3, "n untouched");
        emon.Testport.AssertEq(emon.Port.CellsLen(e.A), 2, "the clone grew by its own");
        emon.Testport.AssertEq(emon.Port.CellsAt(e.A, 1), 5, "5, not 7");
        emon.Testport.AssertText(e.Out, "abc", "the clone's text");
        emon.Testport.AssertEq(e.N, 4, "the clone's n");
    }
    [Xunit.Fact]
    public static void TestFreeEmptiesAndTheArenaIsUsableAgain() {
        emon.Docprobe.Doc d = new emon.Docprobe.Doc();
        emon.Port.CellsPush(d.A, 1);
        emon.Port.CellsPush(d.A, 2);
        emon.Port.CellsFree(d.A);
        emon.Testport.AssertEq(emon.Port.CellsLen(d.A), 0, "freed");
        emon.Testport.AssertEq(emon.Port.CellsPush(d.A, 42), 0, "the next push lands at 0");
        emon.Testport.AssertEq(emon.Port.CellsAt(d.A, 0), 42, "42");
        emon.Port.CellsFree(d.B);
        emon.Testport.AssertEq(emon.Port.CellsLen(d.B), 0, "freeing an empty one is allowed");
    }
